async function addDocumentLink(payload){const [aId,bId]=payload.split('|'),a=state.documents.find(x=>x.id===aId),b=state.documents.find(x=>x.id===bId);if(!a||!b)return;if(!approvedCurrentVersion(a.id)||!approvedCurrentVersion(b.id))return toast('Only approved/current documents can be linked for active use.');if(pairExists(aId,bId))return toast('These documents are already linked.');const rel=inferLinkType(a,b),r=await sb.from('document_links').insert({source_document_id:rel.source.id,target_document_id:rel.target.id,link_type:rel.type,created_by:state.user.id}).select().single();if(r.error)return toast(r.error.message);await refresh('Documents linked.');showDocumentLinks(aId)}
