async function saveReportSchedule(id=''){if(!isAdmin())return;const name=clean($('reportScheduleName')?.value),frequency=$('reportScheduleFrequency')?.value||'MONTHLY',day=Math.min(28,Math.max(1,Number($('reportScheduleDay')?.value)||1)),recipients=clean($('reportScheduleRecipients')?.value).split(',').map(x=>x.trim()).filter(Boolean);if(!name)return toast('Schedule name is required.');const payload={name,frequency,day_of_month:day,day_of_week:Number($('reportScheduleWeekday')?.value)||1,recipients,enabled:!!$('reportScheduleEnabled')?.checked,email_enabled:!!$('reportScheduleEmail')?.checked,updated_at:new Date().toISOString()};let r;if(id)r=await sb.from('report_schedules').update(payload).eq('id',id);else r=await sb.from('report_schedules').insert({...payload,created_by:state.user.id});if(r.error)return toast(r.error.message);closeModal();await refresh('Scheduled report saved.')}
async function toggleReportSchedule(id){if(!isAdmin())return;const x=state.reportSchedules.find(r=>r.id===id);if(!x)return;const r=await sb.from('report_schedules').update({enabled:!x.enabled,updated_at:new Date().toISOString()}).eq('id',id);if(r.error)return toast(r.error.message);await refresh(`Scheduled report ${x.enabled?'disabled':'enabled'}.`)}
async function runReportSchedule(id){if(!isAdmin())return;const x=state.reportSchedules.find(r=>r.id===id);if(!x)return;if(x.frequency==='WEEKLY')return toast('Weekly schedules run through the automatic server report runner. Use Monthly for an immediate in-app test run.');const month=previousMonthValue(),report=await generateMonthlySafetyReport(month,{download:true,archive:true,scheduleId:null});if(report){await sb.from('report_schedules').update({last_run_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',id);await refresh('Scheduled report test run created and archived.')}}
function renderReportSchedules(){const el=$('reportScheduleList');if(!el||!isAdmin())return;if(state.loadErrors.report_schedules){el.innerHTML='<div class="empty">Run the reporting SQL migration to enable scheduled reports.</div>';return}const rows=[...state.reportSchedules].sort((a,b)=>String(a.name).localeCompare(String(b.name)));el.innerHTML=rows.length?rows.map(x=>`<div class="item-card schedule-card ${x.enabled?'traffic-green':'traffic-neutral'}"><div class="row-between"><div><h4>${esc(x.name)}</h4><div class="meta"><span class="badge">${esc(x.frequency||'MONTHLY')}</span><span>${x.frequency==='MONTHLY'?`Day ${Number(x.day_of_month||1)}`:`${['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][Number(x.day_of_week||1)]}`}</span><span>${(x.recipients||[]).length} recipient${(x.recipients||[]).length===1?'':'s'}</span><span>${x.email_enabled?'Email enabled':'Archive only'}</span>${x.last_run_at?`<span>Last run ${fmtDateTime(x.last_run_at)}</span>`:''}</div></div><span class="badge ${x.enabled?'complete':''}">${x.enabled?'Enabled':'Disabled'}</span></div><div class="row">${btn('Edit','secondary',`data-edit-report-schedule="${x.id}"`)}${btn(x.enabled?'Disable':'Enable','ghost',`data-toggle-report-schedule="${x.id}"`)}${btn('Run now','primary',`data-run-report-schedule="${x.id}"`)}</div></div>`).join(''):'<div class="empty">No scheduled reports yet.</div>'}

function renderReports(){document.querySelectorAll('.report-manager-content').forEach(el=>el.hidden=isReportViewer());if(isReportViewer()){const latest=[...state.generatedReports].sort((a,b)=>new Date(b.generated_at||0)-new Date(a.generated_at||0))[0];$('reportStats').innerHTML=[['Reports available',state.generatedReports.length],['Latest',latest?fmtDate(latest.generated_at):'—']].map(([l,n])=>`<div class="stat"><strong>${esc(n)}</strong><span>${l}</span></div>`).join('');renderReportArchive();return}const rows=complianceRows(),ppe=ppeManagerMonthSummary(currentMonthValue());$('reportStats').innerHTML=[['Assignments',rows.length],['Complete',rows.filter(r=>r.code==='COMPLETED').length],['Outstanding',rows.filter(r=>r.code!=='COMPLETED').length],['PPE checks this month',ppe.complete+ppe.issues]].map(([l,n])=>`<div class="stat"><strong>${n}</strong><span>${l}</span></div>`).join('');if($('monthlyReportMonth')&&!$('monthlyReportMonth').value)$('monthlyReportMonth').value=previousMonthValue();renderReportArchive();renderDocumentActivityReport()}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function pdfTable(title,rows,name){if(!window.jspdf?.jsPDF)return toast('PDF library did not load.');const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});doc.setFontSize(16);doc.text(title,14,14);doc.setFontSize(8);doc.text(`Generated ${new Date().toLocaleString('en-GB')} · Safety Tracker v${APP_VERSION}`,14,20);const cols=rows.length?Object.keys(rows[0]):['message'];const body=rows.length?rows.map(r=>cols.map(c=>String(r[c]??''))):[['No matching records']];doc.autoTable({head:[cols.map(c=>c.replaceAll('_',' '))],body,startY:25,styles:{fontSize:7,cellPadding:1.5},headStyles:{fontSize:7}});doc.save(name)}
function downloadReport(type){const rows=complianceRows();if(type==='outstanding')return pdfTable('Outstanding Safety Training Actions',rows.filter(r=>r.code!=='COMPLETED').map(r=>({person:personName(r.user_id),training:r.t.name,type:kindLabel(trainingKind(r.t)),status:r.label,due:fmtDate(r.due),delivery:deliveryText(r.method)})),`safety-outstanding-${todayISO()}.pdf`);if(type==='matrix')return pdfTable('Training Matrix',rows.map(r=>({person:personName(r.user_id),training:r.t.name,type:kindLabel(trainingKind(r.t)),status:r.label,last_signed:fmtDateTime(r.s?.signed_at),next_due:fmtDate(r.due)})),`training-matrix-${todayISO()}.pdf`);if(type==='signoffs'){const normal=state.trainingSignoffs.map(s=>({person:personName(s.user_id),training:s.training_name_snapshot||state.training.find(t=>t.id===s.training_session_id)?.name||'',evidence:'Training sign-off',signed_at:fmtDateTime(s.signed_at),signature_name:s.signature_name||'',reason:''})),exceptions=state.trainingExceptions.map(x=>({person:personName(x.user_id),training:state.training.find(t=>t.id===x.training_session_id)?.name||'',evidence:'ADMIN EXCEPTION',signed_at:fmtDateTime(x.completed_at),signature_name:x.signature_name||'',reason:x.reason||''}));return pdfTable('Training Completion Evidence',[...normal,...exceptions],`training-signoffs-${todayISO()}.pdf`)};if(type==='reviews'){const d=state.versions.filter(v=>v.status==='CURRENT'&&isVersionApproved(v)).map(v=>{const x=state.documents.find(d=>d.id===v.document_id);return {kind:'Document',reference:x?.reference||'',item:x?.title||'',review_date:fmtDate(v.review_date),status:v.review_date&&v.review_date<todayISO()?'Overdue':''}}),t=activeTraining().map(x=>({kind:'Training',reference:trainingReference(x),item:x.name,review_date:fmtDate(x.review_date),status:x.review_date&&x.review_date<todayISO()?'Overdue':''}));return pdfTable('Document and Training Review Dates',[...d,...t],`review-dates-${todayISO()}.pdf`)}}
function backupPayload(){return {exported_at:new Date().toISOString(),safety_tracker_version:APP_VERSION,build_id:BUILD_ID,profiles:state.people,documents:state.documents,document_versions:state.versions,document_links:state.documentLinks,document_reviews:state.documentReviews,training_sessions:state.training,training_assignments:state.trainingAssignments,training_signoffs:state.trainingSignoffs,training_exceptions:state.trainingExceptions,training_delivery_confirmations:state.trainingConfirmations,training_files:state.trainingFiles,training_document_links:state.trainingDocumentLinks,document_activity:state.documentActivity,safety_awareness_items:state.awarenessItems,safety_awareness_assignments:state.awarenessAssignments,safety_awareness_activity:state.awarenessActivity,ppe_items:state.ppeItems,ppe_assignments:state.ppeAssignments,ppe_monthly_checks:state.ppeChecks,ppe_monthly_check_items:state.ppeCheckItems,ppe_alert_queue:state.ppeAlertQueue,report_schedules:state.reportSchedules,generated_reports:state.generatedReports,report_email_log:state.reportEmailLog,historical_document_assignments:state.historicalDocAssignments,historical_document_signoffs:state.historicalDocSignoffs,historical_document_delivery_confirmations:state.historicalDocConfirmations}}
function downloadBackup(){downloadBlob(new Blob([JSON.stringify(backupPayload(),null,2)],{type:'application/json'}),`safety-tracker-v2-backup-${todayISO()}.json`)}
async function listStorageRecursive(prefix=''){const out=[];let offset=0;while(true){const r=await sb.storage.from('safety-files').list(prefix,{limit:100,offset,sortBy:{column:'name',order:'asc'}});if(r.error)throw r.error;if(!r.data?.length)break;for(const item of r.data){const path=prefix?`${prefix}/${item.name}`:item.name;if(item.id)out.push(path);else out.push(...await listStorageRecursive(path))}if(r.data.length<100)break;offset+=100}return out}
async function downloadFullBackup(){if(!window.JSZip)return toast('ZIP library did not load.');try{toast('Building full backup…');const zip=new JSZip();zip.file('database/safety-tracker.json',JSON.stringify(backupPayload(),null,2));const files=await listStorageRecursive('');for(const path of files){const r=await sb.storage.from('safety-files').download(path);if(!r.error&&r.data)zip.file(`files/${path}`,r.data)}downloadBlob(await zip.generateAsync({type:'blob'}),`safety-tracker-v2-full-backup-${todayISO()}.zip`);toast(`Full backup created (${files.length} files).`)}catch(e){toast(e.message||'Full backup failed.')}}

async function renderAdmin(){if(!$('buildDiagnostics'))return;renderReportSchedules();let versionInfo=null;try{versionInfo=await fetch(`version.json?t=${Date.now()}`,{cache:'no-store'}).then(r=>r.json())}catch{}let regs=[];try{regs='serviceWorker' in navigator?await navigator.serviceWorker.getRegistrations():[]}catch{}const arch=state.settings.find(s=>s.setting_key==='architecture_version')?.setting_value||'not found',front=state.settings.find(s=>s.setting_key==='front_end_version')?.setting_value||'not found';$('buildDiagnostics').innerHTML=`<div class="card-list"><div class="item-card compact"><div class="row-between"><span>Loaded JavaScript build</span><strong class="diagnostic-ok">v${APP_VERSION}</strong></div></div><div class="item-card compact"><div class="row-between"><span>version.json</span><strong class="${versionInfo?.version===APP_VERSION?'diagnostic-ok':'diagnostic-warn'}">${esc(versionInfo?.version||'unavailable')}</strong></div></div><div class="item-card compact"><div class="row-between"><span>Service workers registered on this origin</span><strong class="${regs.length?'diagnostic-warn':'diagnostic-ok'}">${regs.length}</strong></div><div class="muted">v2 itself never registers a service worker.</div></div><div class="item-card compact"><div>Database architecture setting: <span class="codeish">${esc(arch)}</span></div><div>Previous front-end setting: <span class="codeish">${esc(front)}</span></div></div><div class="item-card compact"><div>Current URL: <span class="codeish">${esc(location.href)}</span></div><div>Build ID: <span class="codeish">${BUILD_ID}</span></div></div>${Object.keys(state.loadErrors).length?`<div class="danger-note"><strong>Schema/load warnings</strong><br>${Object.entries(state.loadErrors).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')}</div>`:'<div class="success-note">Core tables loaded with no reported schema errors.</div>'}</div>`}
function renderHelp(){$('helpContent').innerHTML=`<div class="help-card"><h3>Documents</h3><p>Documents opens with a live Register first, followed by dedicated indexes for Risk Assessments, COSHH Risk Assessments, Safe Systems of Work, MSDS/Safety Data Sheets and Toolbox Talks. The Register lists every approved/current item under its correct section and can be downloaded as a PDF. Toolbox Talk files are indexed here for access, while assignment and sign-off remain in Training.</p></div><div class="help-card"><h3>Training</h3><p>All completion/sign-off happens in Training. RA and COSHH default to self-training with a 12-month refresher. Admin can change the refresher to 6 months, 12 months, 24 months or On change only. SSW and Toolbox Talks default to instructor-led. A new controlled version stays Pending Approval and creates a fresh training requirement only after it is approved/current. Where a current controlled source or training PDF exists, that exact required file must be opened and audit-recorded before sign-off. Supporting links do not block completion. A Manager/Admin can mark a linked document Required; every Required document must then be approved/current and opened before sign-off.</p></div><div class="help-card"><h3>Pending approval & traffic lights</h3><p>New RA, COSHH RA and SSW versions are not authorised for use or Training until a Manager/Admin opens the exact PDF and digitally approves it. SDS/MSDS uses the same control but is labelled Accepted. Green borders mean approved/current, amber means action is required such as pending approval or review due soon, red means overdue/not approved, and grey means archived or historical.</p></div><div class="help-card"><h3>New document versions</h3><p>If the same controlled reference is uploaded again, v2 compares the actual PDF text. Unchanged content is skipped. Changed content is stored as Pending Approval while the previously approved version remains current. Only after digital approval does the new version become CURRENT and the old one become SUPERSEDED.</p></div><div class="help-card"><h3>Combined PDF packs</h3><p>Bulk Import reads the PDF page by page and splits combined RA, COSHH, SSW and Toolbox Talk packs into individual controlled records using the reference printed on each document. It also splits combined manufacturer SDS/MSDS packs by detecting each genuine SDS first page (Section 1 / 1.1 Product identifier), so an SDS pack imports as separate product records. Shield COSHH forms are grouped by the footer reference such as COSHH-014 | Version 1.2, so a multi-assessment pack does not import as one record. Review the detected page ranges before importing.</p></div><div class="help-card"><h3>Force Sync & Review</h3><p>Force Sync first clears the existing link tables, then re-reads every approved/current stored PDF and rebuilds relationships only from references/titles stated in linked, related, supporting or reference sections. Before rebuilding links, v2 repairs Risk Assessment titles from the first page and aligns SDS names from the manufacturer Section 1.1 Product identifier/name. COSHH then matches its stated substance/SDS wording against those aligned product names and aliases. SDS cleanup removes trailing regulation/subsection text such as “According to …” or “: 1.1”. Missing references are flagged instead of guessed.</p></div><div class="help-card"><h3>Document access & review audit</h3><p>Opening or downloading any file creates a timestamped audit event. RA, COSHH RA, SSW and Toolbox Talk acknowledgement is handled through Training, so those items no longer show a separate user review button. SDS/MSDS, policies, procedures and other reference documents can be marked read/reviewed after the file has first been opened.</p></div><div class="help-card"><h3>Archiving and deleting documents</h3><p>Archiving retains compliance history. Admin can permanently delete only a document that has never been approved/accepted and has no protected training, review or sign-off evidence. Admin Storage Cleanup lists only orphaned files that no database record still references.</p></div><div class="help-card"><h3>Self-training support</h3><p>A self-training user can ask ordinary questions without changing the assignment. If they select Need further training and confirm that they require extra instruction/demonstration, only their individual assignment changes to instructor-led. The master RA/COSHH method and other users remain self-training.</p></div><div class="help-card"><h3>Administrator training exception</h3><p>An administrator can complete only their own outstanding instructor-led assignment as an exception when independent instructor confirmation is not available. The required current file must have been opened first. A reason of at least 10 characters, confirmation and digital signature are mandatory and retained as separate compliance evidence. Normal users cannot use this route.</p></div><div class="help-card"><h3>Person evidence packs</h3><p>Managers/Admins can create an incident-ready evidence pack from a controlled document or Toolbox Talk. Choose a person, current or full history, and whether to include directly linked documents. The PDF includes that person's assignments, sign-offs/signatures, instructor confirmations, admin exceptions and document access history, plus version approval/acceptance history and the full controlled-document review history with outcome, reason/notes, next review and signature, then appends the actual controlled PDFs as supporting evidence.</p></div><div class="help-card"><h3>Safety Awareness</h3><p>Annual Safety Awareness is separate from Training. Users open short practical guidance, optionally follow the official HSE link, then acknowledge that they reviewed it. The acknowledgement is valid for the configured period (12 months for the built-in topics). It supports formal training and task controls but never replaces them. Built-in topics include PPE, Working at Height, COSHH basics, Manual Handling, Slips/Trips, Electrical Safety, Fire Safety and safe use of tools/work equipment.</p></div><div class="help-card"><h3>Monthly PPE checks</h3><p>Each employee checks the PPE assigned to them by the 28th of every month. The check records whether each item is available and in good condition, needs replacement, is missing or is not applicable. Missing/replacement items create a red Manager/Admin action and feed the ordering list and monthly reports. PPE is managed from the app so new items can be added or assigned without a code update. This monthly check supports, but does not replace, pre-use checks.</p></div><div class="help-card"><h3>Monthly reports</h3><p>Managers can generate a monthly Safety Compliance PDF showing training completed in the month, annual awareness reviews, overdue training at month end, pending approvals, approvals/acceptances, controlled reviews and admin exceptions. Generated reports are archived in Safety Tracker. Admin can configure report schedules; unattended email requires the optional server email runner included with this build.</p></div><div class="help-card"><h3>Report Viewer access</h3><p>Admin can invite or convert a user to <strong>Report Viewer</strong>. This access is limited to the Reports archive and report downloads. Report Viewers receive no Training, Safety Awareness or PPE assignments and are excluded from compliance figures. Their report downloads are audit logged.</p></div><div class="help-card"><h3>Version check</h3><p>The header must show <strong>v2.2.6 CLEAN</strong>. Admin → Build diagnostics also checks version.json and service-worker registrations.</p></div>`}

